export type ParsedGraduateInstruction<
  TProgram extends string = typeof ANTE_UP_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    config: TAccountMetas[0];
    financeConfig: TAccountMetas[1];
    market: TAccountMetas[2];
    financeMarket: TAccountMetas[3];
    snapshot: TAccountMetas[4];
    paymentMint: TAccountMetas[5];
    paymentVault: TAccountMetas[6];
    supportPayment: TAccountMetas[7];
    admin: TAccountMetas[8];
    tokenProgram: TAccountMetas[9];
  };
  data: GraduateInstructionData;
};

export function parseGraduateInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedGraduateInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      config: getNextAccount(),
      financeConfig: getNextAccount(),
      market: getNextAccount(),
      financeMarket: getNextAccount(),
      snapshot: getNextAccount(),
      paymentMint: getNextAccount(),
      paymentVault: getNextAccount(),
      supportPayment: getNextAccount(),
      admin: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getGraduateInstructionDataDecoder().decode(instruction.data),
  };
}
